svg.metadata:
flowchart TB
  A["Submit key, expected value, new value and options"]
  B["Compare the current value atomically"]
  C{"Matches expected?"}
  D["Write / delete; successful result is true"]
  E["Keep value and TTL; successful result is false"]
  X["Store error: return a failed HaiResult"]
  A --> B
  B --> C
  C -->|"yes"| D
  C -->|"no"| E
  B -->|"operation fails"| X
  classDef default fill:#edf3ff,stroke:#476aab,color:#172b4d,stroke-width:1.5px;
  classDef good fill:#e9f6ef,stroke:#28734e,color:#17452f,stroke-width:1.5px;
  classDef stop fill:#fff0f0,stroke:#af4040,color:#742b2b,stroke-width:1.5px;
  classDef pending fill:#fff6df,stroke:#a07827,color:#654b18,stroke-width:1.5px;
  class D,E good;
  class X stop;
